// same fields as data, in labs' server order, so the page never calls an API. Preview images are the Sanity PNGs
// downscaled to 464px WebP in public/templates/labs-papers/<slug>.webp.
export type LabsPaper = {
  _id: string
  title: string
  slug: string
  date: string
  dateSort: string
  categories: string[]
  authors: string
  authorNames: string[]
  image: string
  /** Where the row opens. */
  href: string
}

export type LabsPapersContent = {
  title: string
  intro: string
  /** Singular noun for the "N found" line. */
  noun: string
  papers: LabsPaper[]
}

